//! Credential plumbing: the local CA, secret storage and the Basic-auth prompt hook.
//!
//! Secrets (Basic credentials) live in the OS keychain under service [`KEYCHAIN_SERVICE`]
//! (behind the [`SecretStore`] trait, so tests and headless builds can swap it). The API token
//! is ephemeral (regenerated by Pando at each start) and is never persisted. Nothing here logs
//! secrets.

use std::collections::HashMap;
use std::fmt;
use std::future::Future;
use std::path::PathBuf;
use std::pin::Pin;
use std::sync::{Arc, Mutex, PoisonError};

use crate::config::BasicAuth;
use crate::error::{Error, Result};

/// Keychain service name.
pub const KEYCHAIN_SERVICE: &str = "pando-assistant";

/// A boxed future, so the hook traits stay object safe without extra dependencies.
pub type BoxFuture<'a, T> = Pin<Box<dyn Future<Output = T> + Send + 'a>>;

/// `~/.config/pando/tls/ca.crt`, the CA that signs the certificate of `pando serve`.
pub fn default_ca_path() -> Option<PathBuf> {
    #[allow(deprecated)]
    let home = std::env::home_dir()?;
    Some(home.join(".config/pando/tls/ca.crt"))
}

/// Reads the local CA (PEM). `Ok(None)` when the file does not exist.
pub fn load_local_ca(path: &std::path::Path) -> Result<Option<Vec<u8>>> {
    match std::fs::read(path) {
        Ok(bytes) => Ok(Some(bytes)),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(None),
        Err(e) => Err(Error::Config(format!(
            "cannot read CA {}: {e}",
            path.display()
        ))),
    }
}

/// Secret storage (the OS keychain in the app, a map in tests). Errors are plain messages.
pub trait SecretStore: Send + Sync + fmt::Debug {
    /// The stored secret for `account`, if any.
    fn get(&self, account: &str) -> std::result::Result<Option<String>, String>;
    /// Stores (or replaces) the secret for `account`.
    fn set(&self, account: &str, secret: &str) -> std::result::Result<(), String>;
    /// Removes the secret (absent is not an error).
    fn delete(&self, account: &str) -> std::result::Result<(), String>;
}

/// In-memory [`SecretStore`] for tests and headless runs.
#[derive(Default)]
pub struct MemorySecretStore {
    map: Mutex<HashMap<String, String>>,
}

impl fmt::Debug for MemorySecretStore {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("MemorySecretStore(<redacted>)")
    }
}

impl SecretStore for MemorySecretStore {
    fn get(&self, account: &str) -> std::result::Result<Option<String>, String> {
        let map = self.map.lock().unwrap_or_else(PoisonError::into_inner);
        Ok(map.get(account).cloned())
    }
    fn set(&self, account: &str, secret: &str) -> std::result::Result<(), String> {
        let mut map = self.map.lock().unwrap_or_else(PoisonError::into_inner);
        map.insert(account.to_owned(), secret.to_owned());
        Ok(())
    }
    fn delete(&self, account: &str) -> std::result::Result<(), String> {
        let mut map = self.map.lock().unwrap_or_else(PoisonError::into_inner);
        map.remove(account);
        Ok(())
    }
}

/// [`SecretStore`] over the OS keychain.
#[cfg(feature = "keyring-store")]
#[derive(Debug, Default, Clone, Copy)]
pub struct KeyringStore;

#[cfg(feature = "keyring-store")]
impl KeyringStore {
    fn entry(account: &str) -> std::result::Result<keyring::Entry, String> {
        keyring::Entry::new(KEYCHAIN_SERVICE, account).map_err(|e| e.to_string())
    }
}

#[cfg(feature = "keyring-store")]
impl SecretStore for KeyringStore {
    fn get(&self, account: &str) -> std::result::Result<Option<String>, String> {
        match Self::entry(account)?.get_password() {
            Ok(secret) => Ok(Some(secret)),
            Err(keyring::Error::NoEntry) => Ok(None),
            Err(e) => Err(e.to_string()),
        }
    }
    fn set(&self, account: &str, secret: &str) -> std::result::Result<(), String> {
        Self::entry(account)?
            .set_password(secret)
            .map_err(|e| e.to_string())
    }
    fn delete(&self, account: &str) -> std::result::Result<(), String> {
        match Self::entry(account)?.delete_credential() {
            Ok(()) | Err(keyring::Error::NoEntry) => Ok(()),
            Err(e) => Err(e.to_string()),
        }
    }
}

/// Asks the user for Basic credentials (the UI login dialog). Called at most once for a burst
/// of concurrent requests; `None` means the user cancelled.
pub trait CredentialPrompt: Send + Sync {
    /// Prompts for credentials for the server at `base_url`.
    fn prompt<'a>(&'a self, base_url: &'a str) -> BoxFuture<'a, Option<BasicAuth>>;
}

/// Optional hooks of a [`crate::PandoClient`].
#[derive(Clone, Default)]
pub struct AuthHooks {
    /// Where Basic credentials are remembered.
    pub store: Option<Arc<dyn SecretStore>>,
    /// The login dialog.
    pub prompt: Option<Arc<dyn CredentialPrompt>>,
}

impl fmt::Debug for AuthHooks {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("AuthHooks")
            .field("store", &self.store.is_some())
            .field("prompt", &self.prompt.is_some())
            .finish()
    }
}

/// Keychain account for the Basic credentials of `base_url`.
pub(crate) fn basic_account(base_url: &str) -> String {
    format!("basic:{base_url}")
}

pub(crate) fn encode_basic(auth: &BasicAuth) -> String {
    serde_json::json!({"u": auth.username, "p": auth.expose_password()}).to_string()
}

pub(crate) fn decode_basic(raw: &str) -> Option<BasicAuth> {
    let v: serde_json::Value = serde_json::from_str(raw).ok()?;
    Some(BasicAuth::new(v.get("u")?.as_str()?, v.get("p")?.as_str()?))
}
